// NOVEL (hand-authored) — not generated by CLI Printing Press.
// Recorded in .printing-press-patches/garmin-windowed-sync.json.
//
// Calendar arithmetic for the archive walk. Every series walks oldest day
// first (N131 decision D15), so the only window planner here is the forward
// one: the retired backward walk's planBackwardWindow and the newest-first day
// enumeration went with it.
//
// Garmin reports and accepts
// calendar dates ("2026-09-07"), never instants, so every date here is a
// civilDay: a year/month/day with no clock and no zone. Arithmetic runs
// through time.Date in UTC purely as a proleptic-Gregorian calculator, which
// is why a daylight-saving transition in the caller's zone cannot shorten,
// lengthen, or skip a day in a window. The one place the zone matters is
// today(): which calendar day "today" is depends on where the account holder
// is, so that reads the supplied location.
package cli

import (
	"fmt"
	"time"
)

// civilDay is a calendar date with no time and no zone.
type civilDay struct {
	year  int
	month time.Month
	day   int
}

// newCivilDay normalizes an out-of-range field (month 13, day 32) the way
// time.Date does, so callers can do arithmetic without pre-checking.
func newCivilDay(year int, month time.Month, day int) civilDay {
	t := time.Date(year, month, day, 0, 0, 0, 0, time.UTC)
	return civilDay{year: t.Year(), month: t.Month(), day: t.Day()}
}

// dayOf takes the calendar date of an instant as that instant's own zone
// reports it. Callers pass an already-localized time.
func dayOf(t time.Time) civilDay {
	return civilDay{year: t.Year(), month: t.Month(), day: t.Day()}
}

// today is the current calendar date in loc. A nil loc means the machine's
// local zone, which is what a household CLI wants: Garmin's "calendarDate"
// for a night's sleep is the local date, not the UTC one.
func today(now func() time.Time, loc *time.Location) civilDay {
	if loc == nil {
		loc = time.Local
	}
	return dayOf(now().In(loc))
}

func parseCivilDay(s string) (civilDay, error) {
	t, err := time.ParseInLocation("2006-01-02", s, time.UTC)
	if err != nil {
		return civilDay{}, fmt.Errorf("invalid calendar date %q: want YYYY-MM-DD", s)
	}
	return dayOf(t), nil
}

// mustParseCivilDay is for the series catalog's fixed floors, which are
// compile-time constants. It panics only on a literal typo in this package.
func mustParseCivilDay(s string) civilDay {
	d, err := parseCivilDay(s)
	if err != nil {
		panic(err)
	}
	return d
}

func (c civilDay) isZero() bool { return c == civilDay{} }

func (c civilDay) String() string {
	if c.isZero() {
		return ""
	}
	return fmt.Sprintf("%04d-%02d-%02d", c.year, c.month, c.day)
}

func (c civilDay) time() time.Time {
	return time.Date(c.year, c.month, c.day, 0, 0, 0, 0, time.UTC)
}

// addDays moves n calendar days. Negative n moves backwards.
func (c civilDay) addDays(n int) civilDay {
	return dayOf(c.time().AddDate(0, 0, n))
}

func (c civilDay) before(o civilDay) bool { return c.time().Before(o.time()) }
func (c civilDay) after(o civilDay) bool  { return c.time().After(o.time()) }

// daysBetween counts calendar days from a to b inclusive of both ends when
// they are the same day (so a==b is 1). A b before a returns 0.
func daysInclusive(a, b civilDay) int {
	if b.before(a) {
		return 0
	}
	return int(b.time().Sub(a.time())/(24*time.Hour)) + 1
}

func minDay(a, b civilDay) civilDay {
	if a.isZero() {
		return b
	}
	if b.isZero() {
		return a
	}
	if a.before(b) {
		return a
	}
	return b
}

func maxDay(a, b civilDay) civilDay {
	if a.isZero() {
		return b
	}
	if b.isZero() {
		return a
	}
	if a.after(b) {
		return a
	}
	return b
}

// dayWindow is one request's inclusive date range.
type dayWindow struct {
	start civilDay
	end   civilDay
}

func (w dayWindow) String() string { return w.start.String() + ".." + w.end.String() }

func (w dayWindow) days() int { return daysInclusive(w.start, w.end) }

// planForwardWindows splits [from..to] into windows of at most size days,
// oldest first. An empty range (to before from) plans nothing, which is what
// an already-caught-up incremental sync must do: no range, no calls.
//
// The last window is short rather than overshooting past `to`, so an
// incremental run never asks Garmin for days that have not happened.
func planForwardWindows(from, to civilDay, size int) []dayWindow {
	if size < 1 || from.isZero() || to.isZero() || to.before(from) {
		return nil
	}
	var out []dayWindow
	cursor := from
	for !cursor.after(to) {
		end := cursor.addDays(size - 1)
		if end.after(to) {
			end = to
		}
		out = append(out, dayWindow{start: cursor, end: end})
		cursor = end.addDays(1)
	}
	return out
}

// completeDayCeiling is the newest day that can be called complete as of
// `now`: today is still accruing, so it is always the day before today.
// A series may store today's partial row — it just never bookmarks it.
func completeDayCeiling(t civilDay) civilDay { return t.addDays(-1) }
